18	/**
19	 * The marketing segment an owner falls into, formatted {@code '<TIER>_<AREA>'}. Owns the
20	 * tier and area boundaries so they live in one place rather than being scattered across
21	 * callers: the tier is {@code PREMIUM} at membership level 3 or more and {@code STANDARD}
22	 * below it, and the area is {@code METRO} for a known region (see
23	 * {@link CityRegionTable#isKnown(String)}) and {@code REGIONAL} otherwise.
24	 */
25	public final class OwnerSegment {
26	
27	    /** The lowest membership level that earns the {@code PREMIUM} tier. */
28	    private static final int PREMIUM_LEVEL = 3;
29	
30	    private OwnerSegment() {
31	    }
32	
33	    /**
34	     * Format the {@code '<TIER>_<AREA>'} segment for an owner.
35	     *
36	     * @param membershipLevel the owner's membership level (1 to 4)
37	     * @param locality        the owner's canonical region (as returned by
38	     *                        {@link CityRegionTable#regionFor(String)})
39	     * @return one of {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO}
40	     *         or {@code STANDARD_REGIONAL}
41	     */
42	    public static String of(int membershipLevel, String locality) {
43	        String tier = membershipLevel >= PREMIUM_LEVEL ? "PREMIUM" : "STANDARD";
44	        String area = CityRegionTable.isKnown(locality) ? "METRO" : "REGIONAL";
45	        return tier + "_" + area;
46	    }
47	}
