498	     * The owner's age band relative to their registration date: {@code "MINOR"} when
499	     * under 18, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or older.
500	     * Derived from the owner's own birth and registration dates, so it stays consistent
501	     * with them; null until a birth date is on file. See {@link AgeBand}.
502	     */
503	    @Transient
504	    public String getAgeBand() {
505	        if (this.birthDate == null || this.registrationDate == null) {
506	            return null;
507	        }
508	        return AgeBand.asOf(this.birthDate, this.registrationDate).name();
509	    }
510	
511	    /**
512	     * Normalize the registration date before persisting: default it to the server's
513	     * current date when none was supplied, then roll it forward onto a business day so
514	     * every newly persisted owner is registered on a weekday.
515	     */
516	    @PrePersist
517	    void normalizeRegistrationDate() {
518	        if (this.registrationDate == null) {
519	            this.registrationDate = LocalDate.now();
520	        }
521	        this.registrationDate = BusinessDay.rollForward(this.registrationDate);
522	    }
523	
524	    protected Set<Pet> getPetsInternal() {
525	        if (this.pets == null) {
526	            this.pets = new HashSet<>();
527	        }
528	        return this.pets;
529	    }
530	
531	    protected void setPetsInternal(Set<Pet> pets) {
532	        this.pets = pets;
533	    }
534	
535	    public List<Pet> getPets() {
536	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
537	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
538	        return Collections.unmodifiableList(sortedPets);
539	    }
540	
541	    public void setPets(List<Pet> pets) {
542	        this.pets = new HashSet<>(pets);
543	    }
544	
