546	        getPetsInternal().add(pet);
547	        pet.setOwner(this);
548	    }
549	
550	    /**
551	     * Return the Pet with the given name, or null if none found for this Owner.
552	     *
553	     * @param name to test
554	     * @return true if pet name is already in use
555	     */
556	    public Pet getPet(String name) {
557	        return getPet(name, false);
558	    }
559	
560	    /**
561	     * Return the Pet with the given name, or null if none found for this Owner.
562	     *
563	     * @param name to test
564	     * @return true if pet name is already in use
565	     */
566	    public Pet getPet(String name, boolean ignoreNew) {
567	        name = name.toLowerCase();
568	        for (Pet pet : getPetsInternal()) {
569	            if (!ignoreNew || !pet.isNew()) {
570	                String compName = pet.getName();
571	                compName = compName.toLowerCase();
572	                if (compName.equals(name)) {
573	                    return pet;
574	                }
575	            }
576	        }
577	        return null;
578	    }
579	
580	    public Pet getPet(Integer petId) {
581	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
582	    }
