257	    @Override
258	    @Transactional
259	    public void saveOwner(Owner owner) throws DataAccessException {
260	        if (owner.isNew()) {
261	            if (owner.getCustomerCode() == null) {
262	                owner.setCustomerCode(customerCodeGenerator.generateUnique(
263	                    RegionResolver.regionFor(owner.getPostcode(), owner.getCity()),
264	                    owner.getTelephone(), owner.getLastName(),
265	                    ownerRepository::existsByCustomerCode));
266	            }
267	            owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
268	            owner.setBulkSignupWarning(
269	                ownerRepository.countByRegistrationDate(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
270	            owner.setCapacityWarning(
271	                ownerRepository.countByCity(owner.getCity()) >= CITY_CAPACITY_WARNING_THRESHOLD);
272	            owner.setHouseholdId(householdIdFor(owner));
273	            owner.setHouseholdSize(householdSizeIncluding(owner));
274	            owner.setMembershipLevelCap(membershipLevelCapFor(owner));
275	            Optional<Owner> possibleDuplicate = findPossibleDuplicate(owner);
276	            owner.setPossibleDuplicate(possibleDuplicate.isPresent());
277	            owner.setPossibleDuplicateOf(possibleDuplicate.map(Owner::getId).orElse(null));
278	        }
279	        ownerRepository.save(owner);
280	
281	    }
282	
283	    /**
284	     * The deterministic, shared household id this owner maps to, derived from its last
285	     * name and postcode so that owners sharing both belong to the same household.
286	     */
287	    private String householdIdFor(Owner owner) {
288	        return householdIdGenerator.generate(owner.getLastName(), owner.getPostcode());
289	    }
290	
291	    /**
292	     * Size of the household this new owner will belong to once persisted: the owners
293	     * already sharing its household id, plus the owner itself. An owner with no shared
294	     * household id stands alone, so its household size is one.
295	     */
296	    private int householdSizeIncluding(Owner owner) {
297	        if (owner.getHouseholdId() == null) {
298	            return 1;
299	        }
300	        return (int) ownerRepository.countByHouseholdId(owner.getHouseholdId()) + 1;
301	    }
302	
303	    /**
304	     * Count the existing owners that already share the given first and last name,
305	     * compared case-insensitively. Used to stamp a new owner's namesake count at
306	     * registration, before it is itself persisted.
307	     */
308	    private int countNamesakes(String firstName, String lastName) {
309	        return (int) ownerRepository.findByLastNameIgnoreCase(lastName).stream()
310	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName))
311	            .count();
312	    }
313	
314	    /**
315	     * The existing owners that already belong to this owner's household, i.e. the persisted
316	     * owners sharing its computed household id. An owner with no household id (that maps to no
317	     * shared household) has no existing household members. As the household id is derived from
318	     * the last name, the candidates are narrowed by last name before the id is matched.
319	     */
320	    private List<Owner> existingHouseholdMembers(Owner owner) {
321	        String householdId = owner.getHouseholdId();
322	        if (householdId == null) {
323	            return List.of();
324	        }
325	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
326	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
327	            .toList();
328	    }
329	
330	    /**
331	     * The ceiling to stamp on a new owner's membership level: one above the highest membership
332	     * level currently held by an existing member of its household, so the new owner's level
333	     * cannot exceed one above the household maximum. Null when the owner has no existing
334	     * household member, in which case no ceiling applies. See {@link Owner#getMembershipLevel()}.
335	     */
336	    private Integer membershipLevelCapFor(Owner owner) {
337	        return existingHouseholdMembers(owner).stream()
338	            .map(Owner::getMembershipLevel)
339	            .max(Comparator.naturalOrder())
340	            .map(max -> max + 1)
341	            .orElse(null);
342	    }
343	
344	    /**
345	     * Find the existing owner, if any, that this new owner is a possible (soft) duplicate of:
346	     * a live owner that is not a hard duplicate (its {@link Owner#getIdentityKey() identity
347	     * key} differs) yet shares the new owner's phonetic last name (see {@link Soundex}) and
348	     * postcode. When several match, the earliest (lowest id) is chosen. An owner with no
349	     * postcode belongs to no such group, and one that deliberately declared it shares a
350	     * household is never a suspected duplicate.
351	     */
352	    private Optional<Owner> findPossibleDuplicate(Owner owner) {
353	        String postcode = owner.getPostcode();
354	        if (owner.isDeclaredHouseholdMember() || postcode == null || postcode.isBlank()) {
355	            return Optional.empty();
356	        }
357	        String identityKey = owner.getIdentityKey();
358	        return liveOwnersSoundingLike(owner).stream()
359	            .filter(existing -> postcode.equals(existing.getPostcode()))
360	            .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
361	            .min(Comparator.comparing(Owner::getId));
362	    }
363	
364	    /**
365	     * The live (non-deleted) owners whose last name sounds like this owner's, i.e. shares its
366	     * Soundex code. This is the shared candidate set for both hard-duplicate detection and the
367	     * soft match, which group owners by the phonetic sound of the last name (as the identity
368	     * key does) rather than by an exact last-name match.
369	     */
370	    private List<Owner> liveOwnersSoundingLike(Owner owner) {
371	        String soundex = Soundex.of(owner.getLastName());
372	        return ownerRepository.findByDeletedFalse().stream()
373	            .filter(existing -> soundex.equals(Soundex.of(existing.getLastName())))
374	            .toList();
375	    }
376	
377	    @Override
378	    @Transactional(readOnly = true)
379	    public boolean isDuplicateOwner(Owner owner) throws DataAccessException {
380	        String identityKey = owner.getIdentityKey();
381	        return liveOwnersSoundingLike(owner).stream()
382	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
383	    }
384	
385	    @Override
386	    @Transactional(readOnly = true)
387	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
388	        return ownerRepository.findByLastName(lastName);
389	    }
390	
391	    @Override
392	    @Transactional(readOnly = true)
393	    public long countOwnersByCity(String city) throws DataAccessException {
394	        return ownerRepository.countByCity(city);
395	    }
396	
397	    @Override
398	    @Transactional(readOnly = true)
399	    public long countOwnersByRegistrationDate(LocalDate registrationDate) throws DataAccessException {
400	        return ownerRepository.countByRegistrationDate(registrationDate);
401	    }
402	
403	    @Override
404	    @Transactional(readOnly = true)
405	    public Collection<Visit> findVisitsByPetId(int petId) {
406	        return visitRepository.findByPetId(petId);
407	    }
408	
409	    @Override
410	    @Transactional(readOnly = true)
411	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
412	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
413	    }
414	
415	    private <T> T findEntityById(Supplier<T> supplier) {
416	        try {
417	            return supplier.get();
418	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
419	            // Just ignore not found exceptions for Jdbc/Jpa realization
420	            return null;
421	        }
422	    }
423	
424	}
