package org.springframework.samples.petclinic.service;

import java.util.Locale;
import java.util.function.Predicate;

import org.springframework.samples.petclinic.model.MemberId;
import org.springframework.samples.petclinic.model.Sha256;
import org.springframework.stereotype.Component;

/**
 * Builds an owner's {@code memberId}, formatted {@code '<REGION><FY><HASH8><CHK>'} (see
 * {@link MemberId}) where REGION is the owner's canonical region (see
 * {@link org.springframework.samples.petclinic.model.RegionResolver}), FY is the two-digit
 * fiscal year, HASH8 is the first eight upper-case hexadecimal characters of the SHA-256
 * hash over the owner's normalized telephone followed by its last name, and CHK is the
 * member id's Luhn check digit. The identity is derived purely from the owner's own fields,
 * carrying no sequence number.
 */
@Component
public class MemberIdGenerator {

    private static final int HASH_LENGTH = 8;

    /**
     * Build the member id for a new owner.
     *
     * @param region              the owner's canonical region
     * @param fiscalYearShort     the two-digit fiscal year of the owner's registration date
     * @param normalizedTelephone the owner's normalized (E.164) telephone
     * @param lastName            the owner's last name
     * @return the formatted member id, e.g. {@code "NSW261A2B3C4D5"}
     */
    public String generate(String region, int fiscalYearShort, String normalizedTelephone, String lastName) {
        return MemberId.format(region, fiscalYearShort, hash8(normalizedTelephone, lastName));
    }

    /**
     * Build a member id that does not collide with any already in use. The id is derived
     * exactly as {@link #generate(String, int, String, String)}; when that value is already
     * taken, {@code '-<n>'} is appended with the smallest {@code n} of two or more that
     * yields an unused id.
     *
     * @param region              the owner's canonical region
     * @param fiscalYearShort     the two-digit fiscal year of the owner's registration date
     * @param normalizedTelephone the owner's normalized (E.164) telephone
     * @param lastName            the owner's last name
     * @param isTaken             tests whether a candidate id is already in use
     * @return a member id not reported as taken by {@code isTaken}
     */
    public String generateUnique(String region, int fiscalYearShort, String normalizedTelephone, String lastName,
            Predicate<String> isTaken) {
        String base = generate(region, fiscalYearShort, normalizedTelephone, lastName);
        String candidate = base;
        for (int n = 2; isTaken.test(candidate); n++) {
            candidate = base + "-" + n;
        }
        return candidate;
    }

    private String hash8(String normalizedTelephone, String lastName) {
        String identity = safe(normalizedTelephone) + safe(lastName);
        return Sha256.hex(identity).substring(0, HASH_LENGTH).toUpperCase(Locale.ROOT);
    }

    private String safe(String value) {
        return value == null ? "" : value;
    }
}

